    if ([long]$result.Candidate.SchemaVersion-ne4-or$null-ne$result.Candidate.PSObject.Properties['Soak']-or$null-ne$result.Candidate.EvidenceBoundary.PSObject.Properties['Human']-or[string]$result.Candidate.EvidenceClassification -cne 'Issue10RuntimeCandidate' -or [string]$result.Candidate.EvidenceBoundary.RuntimeInput -cne 'SYNTHETIC_FIXTURE_BOUND' -or [string]$result.Candidate.EvidenceBoundary.Runtime -cne 'NOT_OBSERVED' -or [string]$result.Candidate.EvidenceBoundary.Release -cne 'NOT_OBSERVED' -or [bool]$result.Candidate.EvidenceBoundary.CreditGranted -or [string]$result.Candidate.RunNonce -cne $valid.RunNonce) { throw 'Valid Issue #10 fixture crossed the v4 evidence boundary or retained removed fields.' }
    Pass-Test 'valid bilingual candidate remains RuntimeCandidate with dual-hash and nonce binding'
    if(Get-Command Test-Json -ErrorAction SilentlyContinue){$candidateSchema=Join-Path $PSScriptRoot 'issue10-runtime-candidate.schema.json';$missingPerformanceField=($result.Candidate|ConvertTo-Json -Depth 100|ConvertFrom-Json -DateKind String);$missingPerformanceField.Performance.PSObject.Properties.Remove('TelemetryBindingPath');if(($missingPerformanceField|ConvertTo-Json -Depth 100|Test-Json -SchemaFile $candidateSchema -ErrorAction SilentlyContinue)){throw 'Issue #10 schema admitted a missing TelemetryBindingPath.'};Pass-Test 'candidate schema rejects missing performance authority field';$extraPerformanceField=($result.Candidate|ConvertTo-Json -Depth 100|ConvertFrom-Json -DateKind String);$extraPerformanceField.Performance|Add-Member unexpectedAuthority 'forbidden';if(($extraPerformanceField|ConvertTo-Json -Depth 100|Test-Json -SchemaFile $candidateSchema -ErrorAction SilentlyContinue)){throw 'Issue #10 schema admitted an extra performance authority field.'};Pass-Test 'candidate schema rejects extra performance authority field'}
    Assert-Throws { Publish-I10NoClobber -Root $valid.Root -Path $result.CandidatePath -Text 'clobber' -Context 'direct no-clobber publication' } 'no-clobber preserves an existing destination' 'clobber|existing destination'
    Assert-Throws { Invoke-Fixture -Fixture $valid } 'replayed run nonce is rejected before reuse' 'replay'

    $stale = New-I10Fixture; $stale.EvidenceStartedUtc = [DateTimeOffset]::UtcNow.AddHours(-7); Assert-Throws { Invoke-Fixture -Fixture $stale } 'stale invocation window is rejected by trusted clock' 'six-hour|trusted'
    $missingRaw = New-I10Fixture; $missingRawValue = (Read-I10StrictJson -Path $missingRaw.PerformancePath -Context 'missing raw hash').Value; $missingRawValue.provenance.package.receipt.fileSha256 = $null; Write-FixtureJson -Path $missingRaw.PerformancePath -Value $missingRawValue; Assert-Throws { Invoke-Fixture -Fixture $missingRaw } 'missing raw package hash fails closed' 'fileSha256'
    $missingCanonical = New-I10Fixture; $missingCanonicalValue = (Read-I10StrictJson -Path $missingCanonical.PerformancePath -Context 'missing canonical hash').Value; $missingCanonicalValue.provenance.package.receipt.canonicalSha256 = $null; Write-FixtureJson -Path $missingCanonical.PerformancePath -Value $missingCanonicalValue; Assert-Throws { Invoke-Fixture -Fixture $missingCanonical } 'missing canonical package hash fails closed' 'canonicalSha256'
    $missingSidecar=New-I10Fixture;$missingSidecarValue=(Read-I10StrictJson -Path $missingSidecar.PerformancePath -Context 'missing sidecar').Value;$missingSidecarValue.provenance.PSObject.Properties.Remove('performanceTelemetryBinding');Write-FixtureJson $missingSidecar.PerformancePath $missingSidecarValue;Assert-Throws {Invoke-Fixture $missingSidecar} 'missing performance sidecar provenance fails closed' 'performanceTelemetryBinding'
    $tamperedSidecar=New-I10Fixture;[IO.File]::AppendAllText($tamperedSidecar.PerformanceSidecarPath,' ');Assert-Throws {Invoke-Fixture $tamperedSidecar} 'tampered performance sidecar bytes fail closed' 'sidecar.*binding|canonical'
    $legacySessionSidecar=New-I10Fixture;Update-PerformanceSidecarFixture $legacySessionSidecar {param($value)$value.schemaVersion=2;$value.session|Add-Member powerSource 'AC';$value.session|Add-Member thermalState 'Nominal'};Assert-Throws {Invoke-Fixture $legacySessionSidecar} 'legacy power and thermal performance sidecar cannot close schema v3' 'unknown, missing|schemaVersion|source/session/package/raw binding'
    $offsetSidecar=New-I10Fixture;Update-PerformanceSidecarFixture $offsetSidecar {param($value)$time=[DateTimeOffset]::Parse([string]$value.acquisitions[0].appStartUtc);$value.acquisitions[0].appStartUtc=$time.ToOffset([TimeSpan]::FromHours(7)).ToString('O')};Assert-Throws {Invoke-Fixture $offsetSidecar} 'nonzero-offset sidecar process timestamp fails exact UTC guard' 'exact round-trip UTC'
    $stringSequenceSidecar=New-I10Fixture;Update-PerformanceSidecarFixture $stringSequenceSidecar {param($value)$value.acquisitions[0].sequenceNumber='0'};Assert-Throws {Invoke-Fixture $stringSequenceSidecar} 'performance sidecar string sequenceNumber fails native integer guard' 'native JSON integer'
    $stringPreHwndSidecar=New-I10Fixture;Update-PerformanceSidecarFixture $stringPreHwndSidecar {param($value)$value.acquisitions[0].preFirstHwndProof='true'};Assert-Throws {Invoke-Fixture $stringPreHwndSidecar} 'performance sidecar string preFirstHwndProof fails native boolean guard' 'native JSON boolean'
    $stringCreditSidecar=New-I10Fixture;Update-PerformanceSidecarFixture $stringCreditSidecar {param($value)$value.evidenceBoundary.creditGranted='false'};Assert-Throws {Invoke-Fixture $stringCreditSidecar} 'performance sidecar string creditGranted fails native boolean guard' 'native JSON boolean'
    $transplantedCommit=New-I10Fixture;$commitValue=(Read-I10StrictJson -Path $transplantedCommit.PerformanceCommitPath -Context 'transplanted commit').Value;$commitValue.runNonce=('0'*32);Write-FixtureJson $transplantedCommit.PerformanceCommitPath $commitValue;$commitHeld=Read-I10HeldFile -Path $transplantedCommit.PerformanceCommitPath -MaximumBytes 1000000 -Context 'transplanted commit';$performanceValue=(Read-I10StrictJson -Path $transplantedCommit.PerformancePath -Context 'transplanted performance').Value;$performanceValue.provenance.performanceTransactionCommit.bytes=$commitHeld.Length;$performanceValue.provenance.performanceTransactionCommit.fileSha256=$commitHeld.Sha256;$performanceValue.provenance.performanceTransactionCommit.canonicalSha256=Get-I10CanonicalSha256 $commitValue;Write-FixtureJson $transplantedCommit.PerformancePath $performanceValue;Assert-Throws {Invoke-Fixture $transplantedCommit} 'transplanted performance commit nonce fails closed' 'transaction commit does not bind|runNonce'
    $stringCommitCredit=New-I10Fixture;$stringCommitValue=(Read-I10StrictJson -Path $stringCommitCredit.PerformanceCommitPath -Context 'string commit credit').Value;$stringCommitValue.creditGranted='false';Write-FixtureJson $stringCommitCredit.PerformanceCommitPath $stringCommitValue;$stringCommitHeld=Read-I10HeldFile -Path $stringCommitCredit.PerformanceCommitPath -MaximumBytes 1000000 -Context 'string commit credit';$stringCommitReceipt=(Read-I10StrictJson -Path $stringCommitCredit.PerformancePath -Context 'string commit receipt').Value;$stringCommitReceipt.provenance.performanceTransactionCommit.bytes=$stringCommitHeld.Length;$stringCommitReceipt.provenance.performanceTransactionCommit.fileSha256=$stringCommitHeld.Sha256;$stringCommitReceipt.provenance.performanceTransactionCommit.canonicalSha256=Get-I10CanonicalSha256 $stringCommitValue;Write-FixtureJson $stringCommitCredit.PerformancePath $stringCommitReceipt;Assert-Throws {Invoke-Fixture $stringCommitCredit} 'performance commit string creditGranted fails native boolean guard' 'native JSON boolean'
    $missingBinding = New-I10Fixture; $missingBinding.PackageBinding.PSObject.Properties.Remove('IdentityFileSha256'); Assert-Throws { Invoke-Fixture -Fixture $missingBinding } 'missing caller raw package binding is rejected' 'IdentityFileSha256'
    $legacyPerformance=New-I10Fixture;$legacyValue=(Read-I10StrictJson $legacyPerformance.PerformancePath 'legacy performance').Value;$legacyValue.schemaVersion=3;Write-FixtureJson $legacyPerformance.PerformancePath $legacyValue;Assert-Throws {Invoke-Fixture $legacyPerformance} 'legacy performance receipt cannot close v4' 'schema-v4'
    $soakShapedReceipt=New-I10Fixture;$soakReceipt=(Read-I10StrictJson $soakShapedReceipt.PerformancePath 'legacy soak-shaped receipt').Value;$soakReceipt|Add-Member soakBins @();Write-FixtureJson $soakShapedReceipt.PerformancePath $soakReceipt;Assert-Throws {Invoke-Fixture $soakShapedReceipt} 'legacy performance soakBins cannot close v4' 'unknown, missing|exactly'

    $unknownGate = New-I10Fixture; [IO.File]::AppendAllText($unknownGate.ThaiGate, "Authority: self-authored`n"); Assert-Throws { Invoke-Fixture -Fixture $unknownGate } 'unknown gate authority field is rejected by grammar' 'unknown field'
    $legacyAttestation=New-I10Fixture;$legacyText=[IO.File]::ReadAllText($legacyAttestation.ThaiGate).Replace('TargetAgentSessionReferenceEvidenceSource: HerdrCliAgentMetadata','TargetAgentSessionReferenceEvidenceSource: OperatorAttestation');[IO.File]::WriteAllText($legacyAttestation.ThaiGate,$legacyText,[Text.UTF8Encoding]::new($false,$true));Assert-Throws {Invoke-Fixture $legacyAttestation} 'legacy operator attestation cannot earn new PASS evidence' 'Herdr CLI Agent metadata'
    $unobservableSession=New-I10Fixture;$unobservableText=[IO.File]::ReadAllText($unobservableSession.EnglishGate).Replace('TargetAgentSessionReferenceObservableByGate: true','TargetAgentSessionReferenceObservableByGate: false');[IO.File]::WriteAllText($unobservableSession.EnglishGate,$unobservableText,[Text.UTF8Encoding]::new($false,$true));Assert-Throws {Invoke-Fixture $unobservableSession} 'unobservable native session cannot earn new PASS evidence' 'directly observable'
    $malformedGate = New-I10Fixture; [IO.File]::AppendAllText($malformedGate.EnglishGate, "ignored free-form text`n"); Assert-Throws { Invoke-Fixture -Fixture $malformedGate } 'malformed ignored gate line is rejected by grammar' 'malformed or ignored'
    $selfAuthored = New-I10Fixture; $identityValue = (Read-I10StrictJson -Path $selfAuthored.Package.IdentityPath -Context 'self-authored identity').Value; $identityValue | Add-Member -NotePropertyName authority -NotePropertyValue 'operator'; Write-FixtureJson -Path $selfAuthored.Package.IdentityPath -Value $identityValue; Assert-Throws { Invoke-Fixture -Fixture $selfAuthored } 'self-authored package authority field is rejected by exact identity schema' 'unknown, missing'

    $swap = New-I10Fixture; $swapState = [pscustomobject]@{ Blocked = $false }; Set-I10TestHook -Hook { param($name,$transaction,$data); if ($name -ceq 'AfterPackageBinding') { foreach ($targetPath in @($swap.Package.IdentityPath,$swap.Package.ArchivePath)) { $replacement = Join-Path $swap.Root ([IO.Path]::GetFileName($targetPath) + '.replacement'); $backup = Join-Path $swap.Root ([IO.Path]::GetFileName($targetPath) + '.backup'); [IO.File]::WriteAllText($replacement, 'replacement'); try { [IO.File]::Replace($replacement, $targetPath, $backup); throw 'replacement unexpectedly succeeded' } catch { if ($_.Exception -is [IO.IOException] -or $_.Exception.InnerException -is [IO.IOException] -or [string]$_.Exception.Message -match 'used by another process|sharing violation|being used') { $swapState.Blocked = $true } else { throw } } } } }; try { $null = Invoke-Fixture -Fixture $swap } finally { Set-I10TestHook -Hook $null }; if (-not $swapState.Blocked) { throw 'post-read package/leaf swap was not blocked by held read handles.' }; Pass-Test 'post-read package and identity leaf replacement is blocked by held handles'
    $hardlink = New-I10Fixture; $hardlinkPath = Join-Path $hardlink.Package.PackageRoot 'identity-hardlink'; Set-I10TestHook -Hook { param($name,$transaction,$data); if ($name -ceq 'AfterEvidenceValidation') { New-Item -ItemType HardLink -Path $hardlinkPath -Target $hardlink.Package.IdentityPath -Force | Out-Null } }; try { Assert-Throws { Invoke-Fixture -Fixture $hardlink } 'hardlink count change reaches final identity guard' 'NumberOfLinks|identity' } finally { Set-I10TestHook -Hook $null; if (Test-Path -LiteralPath $hardlinkPath) { Remove-Item -LiteralPath $hardlinkPath -Force } }
