    $badPng = New-I10Fixture; $badPngValue = (Read-I10StrictJson -Path $badPng.ThaiWidget -Context 'arbitrary PNG').Value; $badCapture = Join-Path (Split-Path -Parent $badPng.ThaiWidget) 'dashboard.png'; [IO.File]::WriteAllBytes($badCapture, [Text.Encoding]::UTF8.GetBytes('arbitrary png')); $badCaptureHeld = Read-I10HeldFile -Path $badCapture -MaximumBytes 100000 -Context 'arbitrary png'; $badPngValue.Dashboard.CaptureBytes = $badCaptureHeld.Length; $badPngValue.Dashboard.CaptureSha256 = $badCaptureHeld.Sha256; Write-FixtureJson -Path $badPng.ThaiWidget -Value $badPngValue; Assert-Throws { Invoke-Fixture -Fixture $badPng } 'arbitrary PNG bytes fail the capture guard' 'PNG signature'
    $publicationRace = New-I10Fixture; $sentinel = 'publication-race-sentinel'; Set-I10TestHook -Hook { param($name,$transaction,$data); if ($name -ceq 'AfterDestinationCheck') { [IO.File]::WriteAllText([string]$data, $sentinel, [Text.UTF8Encoding]::new($false, $true)) } }; try { Assert-Throws { Invoke-Fixture -Fixture $publicationRace } 'publication race cannot clobber a concurrent destination' 'already exists|clobber|no-clobber' } finally { Set-I10TestHook -Hook $null }; if ([IO.File]::ReadAllText($publicationRace.OutputPath) -cne $sentinel) { throw 'Publication race overwrote the unowned destination.' }; Pass-Test 'publication race preserves the unowned destination'
    $postMoveRace = New-I10Fixture; $postMoveHardlink = Join-Path $postMoveRace.Package.PackageRoot 'identity-post-move-hardlink'; $postMoveState = [pscustomobject]@{ HookReached = $false; HardlinkCreated = $false }; Set-I10TestHook -Hook { param($name,$transaction,$data); if ($name -ceq 'AfterPublishedCandidateVerification') { $postMoveState.HookReached = $true; New-Item -ItemType HardLink -Path $postMoveHardlink -Target $postMoveRace.Package.IdentityPath -Force | Out-Null; $postMoveState.HardlinkCreated = $true } }; try { Assert-Throws { Invoke-Fixture -Fixture $postMoveRace } 'post-move input hardlink reaches the final transaction guard' 'NumberOfLinks changed|transaction after published candidate verification' } finally { Set-I10TestHook -Hook $null; if (Test-Path -LiteralPath $postMoveHardlink) { Remove-Item -LiteralPath $postMoveHardlink -Force } }; if (-not $postMoveState.HookReached -or -not $postMoveState.HardlinkCreated) { throw 'Post-move publication hook did not create the hostile admitted-input hardlink.' }; if (Test-Path -LiteralPath $postMoveRace.OutputPath) { throw 'Post-move rejection left a transaction-owned published candidate.' }; $postMoveStages = @(Get-ChildItem -LiteralPath $postMoveRace.Root -Filter '.issue10-stage-*.json' -File -ErrorAction SilentlyContinue); if ($postMoveStages.Count -ne 0) { throw 'Post-move rejection left a staging candidate.' }; Pass-Test 'post-move input hardlink rejects before authority return and cleans owned publication'

    Pass-Test 'fixture path never starts Herdr, HerdrOps, or an application process'
    [pscustomobject][ordered]@{ EvidenceClassification = 'SyntheticVerifierSelftest'; PositiveCases = $script:Passed; NegativeCases = ($script:Passed - 2); Runtime = 'NOT_OBSERVED'; Release = 'NOT_OBSERVED'; CreditGranted = $false }
